    fun signsIn(category: SignCategory): List<TrafficSign> =
        signs.filter { sign -> sign.category == category }

    fun signById(id: String): TrafficSign? =
        signs.firstOrNull { sign -> sign.id == id }

    fun categoryIconRes(category: SignCategory): Int {
        return when (category) {
            SignCategory.Police -> R.drawable.kategoria_rendori
            SignCategory.RouteType -> R.drawable.kategoria_utvonaltipus
            SignCategory.Priority -> R.drawable.kategoria_elsobseg
            SignCategory.Mandatory -> R.drawable.kategoria_utasitastado
            SignCategory.Prohibitory -> R.drawable.kategoria_tilalmi
            SignCategory.Warning -> R.drawable.kategoria_veszely
            SignCategory.Information -> R.drawable.kategoria_tajekoztato
            SignCategory.Additional -> R.drawable.kategoria_kiegeszito
            SignCategory.RoadMarking -> R.drawable.kategoria_utburkolati
            SignCategory.TrafficLight -> R.drawable.kategoria_fenyjelzo
        }
    }

    fun categoryTitleRes(category: SignCategory): Int {
        return when (category) {
            SignCategory.Police -> R.string.kategoria_rendori
            SignCategory.RouteType -> R.string.kategoria_utvonaltipus
            SignCategory.Priority -> R.string.kategoria_elsobsegetszabalyozo
            SignCategory.Mandatory -> R.string.kategoria_utasitastado
            SignCategory.Prohibitory -> R.string.kategoria_tilalmi
            SignCategory.Warning -> R.string.kategoria_veszelytjelzo
            SignCategory.Information -> R.string.kategoria_tajekoztatastado
            SignCategory.Additional -> R.string.kategoria_kiegeszito
            SignCategory.RoadMarking -> R.string.kategoria_utburkolatijelek
            SignCategory.TrafficLight -> R.string.kategoria_fenyjelzokeszulekek
        }
    }
